import { AsyncPipe, NgIf } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  TrackByFunction,
} from '@angular/core';
import {
  FeatureDirective,
  ImageGroup,
  Product,
  isNotNullable,
  useFeatureStyles,
} from '@spartacus/core';
import { BehaviorSubject, Observable, combineLatest, of } from 'rxjs';
import { distinctUntilChanged, filter, map, tap } from 'rxjs/operators';
import { CarouselScrollingComponent } from '../../../shared/components/carousel-scrolling/carousel-scrolling.component';
import { CarouselComponent } from '../../../shared/components/carousel/carousel.component';
import { MediaComponent } from '../../../shared/components/media/media.component';
import { LcpContextDirective } from '../../../shared/lcp-context/lcp-context.directive';
import { CurrentProductService } from '../current-product.service';

@Component({
  selector: 'cx-product-images',
  templateUrl: './product-images.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    NgIf,
    LcpContextDirective,
    MediaComponent,
    CarouselScrollingComponent,
    CarouselComponent,
    AsyncPipe,
    FeatureDirective,
  ],
})
export class ProductImagesComponent {
  protected mainMediaContainer = new BehaviorSubject<any>(null);

  protected product$: Observable<Product> = this.currentProductService
    .getProduct()
    .pipe(
      filter(isNotNullable),
      distinctUntilChanged(),
      tap((p: Product) => {
        this.mainMediaContainer.next(p.images?.PRIMARY ? p.images.PRIMARY : {});
      })
    );

  thumbs$: Observable<any[]> = this.product$.pipe(
    map((p: Product) => this.createThumbs(p))
  );

  mainImage$: Observable<any> = combineLatest([
    this.product$,
    this.mainMediaContainer,
  ]).pipe(map(([, container]) => container));

  constructor(protected currentProductService: CurrentProductService) {
    useFeatureStyles('reserveSpaceForImagesOnPdpAndPlp');
    useFeatureStyles('productCarouselScrolling');
  }

  openImage(item: any): void {
    this.mainMediaContainer.next(item);
  }

  isActive(thumbnail: ImageGroup): Observable<boolean> {
    return this.mainMediaContainer.pipe(
      filter(Boolean),
      map((container: any) => {
        return (
          container.zoom &&
          container.zoom.url &&
          thumbnail.zoom &&
          thumbnail.zoom.url &&
          container.zoom.url === thumbnail.zoom.url
        );
      })
    );
  }

  /** find the index of the main media in the list of media */
  getActive(thumbs: any[]): Observable<number> {
    return this.mainMediaContainer.pipe(
      filter(Boolean),
      map((container: any) => {
        const current = thumbs.find(
          (t) =>
            t.media &&
            container.zoom &&
            t.media.container &&
            t.media.container.zoom &&
            t.media.container.zoom.url === container.zoom.url
        );
        return thumbs.indexOf(current);
      })
    );
  }

  /**
   * Return an array of CarouselItems for the product thumbnails.
   * In case there are less then 2 thumbs, we return null.
   */
  private createThumbs(product: Product): Observable<any>[] {
    if (
      !product.images ||
      !product.images.GALLERY ||
      (Array.isArray(product.images.GALLERY) &&
        product.images.GALLERY.length < 2)
    ) {
      return [];
    }

    return (<any[]>product.images.GALLERY).map((c) => of({ container: c }));
  }

  trackByFn: TrackByFunction<Product> = (_index: number, item: Product) =>
    item?.code;
}
